      const lastDays = b.lastActivity ? Math.floor((Date.now() - new Date(b.lastActivity).getTime()) / 864e5) : Infinity;
      const cardCls = lastDays > 7 ? "yellow" : lastDays > 15 ? "red" : "";
      html += '<div class="seg-vendor-card ' + cardCls + '">';
