      html += "<div><b>" + escapeHtml(it.client || "-") + '</b><br><span style="font-size:10px;color:#94a3b8">' + escapeHtml(it.loc || "") + "</span></div>";
      html += '<div style="font-size:10px;color:#64748b">' + escapeHtml(it.ultimaAccion || "-") + "</div>";
      html += "<div><b>" + escapeHtml(it.problema || "-") + '</b><br><span style="color:#0d9488;font-weight:700">&rarr; ' + escapeHtml(it.accion || "") + "</span>" + actionBtn + "</div>";
